from __future__ import annotations

import re

__all__ = ['sort_versions']

_VERSION_RE = re.compile(
    r'^(?P<major>\d+)\.'
    r'(?P<minor>\d+)\.'
    r'(?P<patch>\d+)'
    r'(?:-(?P<prerelease>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?'
    r'(?:\+(?P<build>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?'
    r'$'
)

# A pre-release identifier key: numeric identifiers (0) sort before alphanumeric ones (1).
_IdentifierKey = tuple[int, int | str]


def _parse_version(
    version: str,
) -> tuple[int, int, int, tuple[_IdentifierKey, ...] | None]:
    match = _VERSION_RE.fullmatch(version)
    if match is None:
        raise ValueError(f'Invalid semantic version: {version!r}')

    prerelease = match['prerelease']
    if prerelease is None:
        identifiers = None
    else:
        identifiers = tuple(
            (0, int(identifier)) if identifier.isdigit() else (1, identifier)
            for identifier in prerelease.split('.')
        )

    return int(match['major']), int(match['minor']), int(match['patch']), identifiers


def _sort_key(version: str) -> tuple[int, int, int, int, tuple[_IdentifierKey, ...]]:
    major, minor, patch, prerelease = _parse_version(version)
    if prerelease is None:
        # A version without a pre-release has higher precedence than one with it.
        return major, minor, patch, 1, ()
    return major, minor, patch, 0, prerelease


def sort_versions(vs: list[str]) -> list[str]:
    """Return *vs* sorted by SemVer 2.0.0 precedence, lowest first.

    Build metadata is ignored for ordering, and versions that tie keep their
    input order.
    """
    return sorted(vs, key=_sort_key)
